from __future__ import annotations

from dataclasses import asdict, dataclass

@dataclass(frozen=True)
class Feature:
    id: str
    category: str
    name: str
    executor: str
    status: str
    safety: str

# Status AVAILABLE berarti feature memiliki executor/adapter yang dapat dipanggil.
# Ketersediaan executor tidak menjamin finding; hasil runtime memakai DETECTED,
# NOT DETECTED, SKIPPED, NOT TESTED, atau INCONCLUSIVE berdasarkan evidence.
