def catalog(category=None):
    return [asdict(x) for x in FEATURES if category is None or x.category.lower()==category.lower()]

def counts():
    return {cat:{"total":len([x for x in FEATURES if x.category==cat]),"available":len([x for x in FEATURES if x.category==cat and x.status=="AVAILABLE"]),"planned":len([x for x in FEATURES if x.category==cat and x.status=="PLANNED"])} for cat in {"BUG_BOUNTY","OSINT","REVERSE"}}
